CREATE OR REPLACE FUNCTION eflow_r9.guard_staffing_removal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from eflow_r9.staffing_removals where tx=pg_catalog.pg_current_xact_id()) then
  if tg_op<>'UPDATE' then
   raise exception 'Confirmed member removal permits only its exact current staffing cleanup' using errcode='42501';
  end if;
  if not eflow_r9.staffing_removal_allowed(tg_table_name,to_jsonb(old),to_jsonb(new)) then
   raise exception 'Confirmed member removal cannot change work facts or unrelated staffing' using errcode='42501';
  end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_r9.serialize()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j jsonb;pid uuid;begin
 j:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 if tg_table_name in ('projects','personal_projects') then pid:=(j->>'id')::uuid;
 elsif tg_table_name='tasks' then pid:=(j->>'linked_project_id')::uuid;
 elsif tg_table_name='personal_tasks' then pid:=(j->>'project_id')::uuid;
 elsif tg_table_name in ('subtasks','personal_subtasks') then pid:=coalesce((select linked_project_id from public.tasks where id=(j->>'task_id')::uuid),(select project_id from public.personal_tasks where id=(j->>'task_id')::uuid));
 elsif tg_table_name='project_office_members' then select project_id into pid from public.project_offices where id=(j->>'project_office_id')::uuid;
 else pid:=(j->>'project_id')::uuid;end if;
 if pid is not null then perform pg_advisory_xact_lock(hashtextextended('r9:'||pid::text,0));end if;
 if tg_op='DELETE' then return old;else return new;end if;
end $function$

CREATE OR REPLACE FUNCTION eflow_evidence.guard_task_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare attempt eflow_evidence.attempts; files jsonb;
begin
  if new.latest_submission is not distinct from old.latest_submission then return new; end if;
  if auth.role() = 'service_role' or (auth.uid() is null and coalesce(auth.role(), '') = '') then return new; end if;
  select * into attempt from eflow_evidence.attempts a
  where a.kind = 'task' and a.task_id = new.id and a.submission_id::text = new.latest_submission ->> 'id';
  if not found or attempt.creation_xid <> pg_current_xact_id()
     or attempt.actor_id is distinct from auth.uid() then
    raise exception 'Submission snapshot must come from the current validated submission' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'fileName', a.file_name, 'filePath', a.file_path, 'fileSize', a.file_size, 'mimeType', a.mime_type
  ) order by incoming.position), '[]'::jsonb) into files
  from jsonb_array_elements(coalesce(new.latest_submission -> 'attachments', '[]'::jsonb)) with ordinality as incoming(item, position)
  join public.task_attachments a on a.submission_id = attempt.submission_id
    and a.file_path = incoming.item ->> 'filePath';
  if jsonb_array_length(files) <> (select count(*) from public.task_attachments a where a.submission_id = attempt.submission_id) then
    raise exception 'Submission snapshot does not match its validated evidence' using errcode = '22023';
  end if;
  new.latest_submission := jsonb_set(new.latest_submission, '{attachments}', files);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_super_admin_task_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and public.is_super_admin(auth.uid()) then
    raise exception 'Admin task access is read-only. Ask the responsible organization to make this change.'
      using errcode = '42501';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION eflow_r7.check_completion_commit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r uuid;target uuid;is_root boolean;personal boolean;
begin
 if tg_table_name in ('tasks','personal_tasks') then r:=case when tg_op='DELETE' then old.id else new.id end;
 else r:=case when tg_op='DELETE' then old.task_id else new.task_id end;end if;
 -- The BEFORE writer/entry-point lock remains held through this deferred check
 -- and commit. Later writes in this transaction also schedule this check, even
 -- when the caller switches constraints to IMMEDIATE. Historical approvals
 -- from another transaction are intentionally not re-decided or revoked.
 for target in select unnest(approved_ids) from eflow_r7.completion_locks
  where root_id=r and approval_xid=pg_catalog.pg_current_xact_id() loop
  personal:=exists(select 1 from public.personal_tasks where id=r);
  is_root:=target=r;
  if personal then
   if is_root then
    if not exists(select 1 from public.personal_tasks where id=target and status='done') then continue;end if;
   elsif not exists(select 1 from public.personal_subtasks where id=target and status='completed') then continue;
   end if;
  else
   if is_root then
    if not exists(select 1 from public.tasks where id=target and status='completed') then continue;end if;
   elsif not exists(select 1 from public.subtasks where id=target and status='completed') then continue;
   end if;
  end if;
  perform eflow_r7.require_completed_descendants(r,target);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION eflow_r7.lock_completion_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r uuid;v_id uuid;approved boolean:=false;
begin
 if tg_table_name in ('tasks','personal_tasks') then r:=case when tg_op='DELETE' then old.id else new.id end;
 else r:=case when tg_op='DELETE' then old.task_id else new.task_id end;end if;
 perform eflow_r7.lock_completion(r);
 if tg_op<>'DELETE' and tg_table_name in ('tasks','subtasks','personal_tasks','personal_subtasks') then
  approved:=(tg_op='INSERT' or new.status is distinct from old.status) and new.status=case when tg_table_name='personal_tasks' then 'done' else 'completed' end;
  if approved then v_id:=new.id;end if;
 end if;
 if approved then
  update eflow_r7.completion_locks set approved_ids=array_append(approved_ids,v_id)
  where root_id=r and not(v_id=any(approved_ids));
  -- Give an actionable error before the unchanged legacy parent guard; the
  -- deferred check below still enforces the final state at commit.
  perform eflow_r7.require_completed_descendants(r,v_id);
 end if;
 if tg_op='DELETE' then return old;else return new;end if;
end $function$

CREATE OR REPLACE FUNCTION eflow_r7.guard_operation_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb:=case when tg_op<>'INSERT' then to_jsonb(old) else '{}' end;
 b jsonb:=case when tg_op<>'DELETE' then to_jsonb(new) else '{}' end;
 root_id uuid; r jsonb; node_id uuid; cmd text;payload jsonb;
begin
 root_id:=case when tg_table_name in ('tasks','personal_tasks') then (b->>'id')::uuid else coalesce((a->>'task_id')::uuid,(b->>'task_id')::uuid) end;
 if tg_table_name='tasks' and tg_op='UPDATE' and eflow_phase6.project_deletion_detach(a,b) then return new;end if;
 r:=eflow_r7.root(root_id);if r is null then if tg_op='DELETE' then return old;else return new;end if;end if;
 -- Preserve the private R9 UPDATE-only staffing removal, never a client marker
 -- or a structural bypass. Existing R9 authority/preview/serialization is kept.
 if tg_op='UPDATE' and eflow_r9.internal((r->>'project')::uuid) and
  (a-array['lead_id','assigned_to','recommendation_lead_id','assigned_to_ids','team_member_ids','team_member_names','assignee_name','reviewer_id','backup_reviewer_id','revision','updated_at'])=
  (b-array['lead_id','assigned_to','recommendation_lead_id','assigned_to_ids','team_member_ids','team_member_names','assignee_name','reviewer_id','backup_reviewer_id','revision','updated_at']) then return new;end if;
 -- Deleted task records may only move to this project's default group during
 -- authorized empty-group cleanup. No work fields or staffing may change.
 if tg_table_name='tasks' and tg_op='UPDATE' and a->>'deleted_at' is not null and
  b->>'deleted_at' is not null and a->>'group_id' is distinct from b->>'group_id' and
  (a-array['group_id','updated_at'])=(b-array['group_id','updated_at']) and
  auth.uid() is not null and exists(
   select 1 from public.project_groups g join public.projects p on p.id=g.project_id
   where (g.id=(b->>'group_id')::uuid or b->>'group_id' is null) and g.project_id=(a->>'linked_project_id')::uuid
    and p.status not in ('completed','archived')
    and public.can_create_scoped_work(p.org_id,auth.uid()) and public.can_manage_project(p.id,auth.uid())
  ) then return new;end if;
 if auth.uid() is not null and not coalesce(eflow_r7.read_root(root_id),false) then raise exception 'Current work access required' using errcode='42501';end if;
 if tg_table_name in ('tasks','personal_tasks') then
  if tg_op='UPDATE' and coalesce(b->>'lead_id',b->>'assigned_to',b->>'recommendation_lead_id') is distinct from coalesce(a->>'lead_id',a->>'assigned_to',a->>'recommendation_lead_id') then
   cmd:='root_lead';payload:=jsonb_build_object('lead',coalesce(b->>'lead_id',b->>'assigned_to',b->>'recommendation_lead_id'),'people',b->'team_member_ids');
   if tg_table_name='personal_tasks' then payload:=payload-'people';end if;
  elsif tg_op='UPDATE' and b->'team_member_ids' is distinct from a->'team_member_ids' then cmd:='contributors';payload:=jsonb_build_object('people',b->'team_member_ids');end if;
 else
  node_id:=coalesce((a->>'id')::uuid,(b->>'id')::uuid);
  if tg_op='DELETE' then cmd:='delete';payload:=jsonb_build_object('id',node_id);
  elsif tg_op='INSERT' then cmd:='create';payload:=jsonb_build_object('id',node_id,'parent',b->'parent_subtask_id');
  elsif b->'parent_subtask_id' is distinct from a->'parent_subtask_id' then cmd:='move';payload:=jsonb_build_object('id',node_id,'parent',b->'parent_subtask_id');
  elsif b->'sibling_order' is distinct from a->'sibling_order' or b->'position' is distinct from a->'position' and not eflow_r7.internal(root_id) then cmd:='order';payload:=jsonb_build_object('parent',a->'parent_subtask_id');
  elsif b->'is_standalone' is distinct from a->'is_standalone' then cmd:='edit';payload:=jsonb_build_object('id',node_id,'standalone',b->'is_standalone');
  elsif b->'lead_id' is distinct from a->'lead_id' or b->'assigned_to_ids' is distinct from a->'assigned_to_ids' then
   -- Canonical transfer/move clears descendants after checking the full scope.
   if b->>'lead_id' is null and eflow_r7.internal(root_id) and b->'assigned_to_ids'=a->'assigned_to_ids' then return new;end if;
   cmd:='staff';payload:=jsonb_build_object('id',node_id,'lead',b->'lead_id','people',b->'assigned_to_ids');
  elsif b->'title' is distinct from a->'title' or b->'due_date' is distinct from a->'due_date' then
   cmd:='edit';payload:=jsonb_build_object('id',node_id,'title',b->'title','due',b->'due_date','standalone',b->'is_standalone');
  end if;
 end if;
 if cmd is not null then perform eflow_r7.require_operation(root_id,cmd,payload);end if;
 if tg_op='DELETE' then return old;else return new;end if;
end $function$

CREATE OR REPLACE FUNCTION eflow_office_management.guard_removed_responsibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.proposed_office_identity_id is not null and exists(
    select 1 from public.project_office_identities i where i.id = new.proposed_office_identity_id and i.provenance->>'removed' = 'true') then
    raise exception 'Choose an Office that is still in this project.' using errcode = '22023';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.phase3_guard_task_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.linked_project_id is null then new.group_id:=null;
 elsif (new.group_id is null and new.deleted_at is null) or (tg_op='UPDATE' and new.linked_project_id is distinct from old.linked_project_id) then
  select id into new.group_id from public.project_groups where project_id=new.linked_project_id order by is_default desc,position,created_at,id limit 1;
 end if;
 if new.group_id is not null and not exists(select 1 from public.project_groups where id=new.group_id and project_id=new.linked_project_id) then
  raise exception 'Choose a group from this project' using errcode='23514';
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION eflow_phase65.guard_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i public.project_office_identities;begin
 -- An accepted project guest can activate named-Office work without a directory Head.
 -- Only this one pending marker may change; all work/staffing facts stay identical.
 if tg_op='UPDATE' and old.proposed_office_identity_id is not null and new.proposed_office_identity_id is null
 and old.status='pending_assignment' and new.assigned_to is null and new.recommendation_lead_id is null
 and (to_jsonb(old)-array['proposed_office_identity_id','updated_at'])=(to_jsonb(new)-array['proposed_office_identity_id','updated_at'])
 and exists(select 1 from public.project_office_work w
 join public.project_office_identities office_record on office_record.id=w.identity_id join public.projects p on p.id=w.project_id
 join public.project_office_people o on o.identity_id=office_record.id join public.project_invitation_requests r on r.id=o.request_id
 join public.project_guest_members m on m.request_id=r.id
 where w.task_id=old.id and office_record.id=old.proposed_office_identity_id and office_record.canonical_office_id is null
 and coalesce(office_record.provenance->>'removed','false')<>'true' and p.status not in ('completed','archived')
 and r.state='accepted' and m.ended_at is null and (m.access_end is null or m.access_end>now())
 and eflow_r7.member(p.id,m.office_id,r.accepted_by)) then return new;end if;
 if tg_op='UPDATE' and old.proposed_office_identity_id is not null and new.proposed_office_identity_id is not null and new.org_id is distinct from old.org_id then raise exception 'Resolve proposed responsibility atomically before changing canonical Office' using errcode='42501';end if;
 if tg_op='UPDATE' and old.proposed_office_identity_id is not null and (new.linked_project_id is distinct from old.linked_project_id or new.source_collaboration_draft_id is distinct from old.source_collaboration_draft_id) then raise exception 'Project work identity is protected' using errcode='42501';end if;
 if (tg_op='INSERT' and new.proposed_office_identity_id is not null) or (tg_op='UPDATE' and new.proposed_office_identity_id is distinct from old.proposed_office_identity_id) then
  perform eflow_phase65.require_lead(new.linked_project_id,auth.uid());
  if tg_op='UPDATE' and old.proposed_office_identity_id is not null and new.proposed_office_identity_id is null then
   select * into i from public.project_office_identities where id=old.proposed_office_identity_id;
   if i.canonical_office_id is null or new.org_id is distinct from i.canonical_office_id or old.status<>'pending_assignment' or new.status<>'pending_assignment' or new.assigned_to is not null or new.recommendation_lead_id is not null or cardinality(coalesce(new.team_member_ids,'{}'::uuid[]))>0 or not exists(select 1 from public.project_offices where id=i.project_office_id and invitation_status='joined' and relationship_type<>'observer') then raise exception 'Resolve proposed responsibility to a joined canonical Office' using errcode='42501';end if;
  end if;
 end if;
 if new.proposed_office_identity_id is not null then
  if new.status not in ('pending_assignment','cancelled') or new.assigned_to is not null or new.recommendation_lead_id is not null or cardinality(coalesce(new.team_member_ids,'{}'::uuid[]))>0 or nullif(btrim(new.team_id),'') is not null then raise exception 'Resolve proposed Office identity before staffing or execution' using errcode='42501';end if;
  if exists(select 1 from public.subtasks where task_id=new.id and (status<>'todo' or assigned_to is not null or cardinality(coalesce(assigned_to_ids,'{}'::uuid[]))>0)) or exists(select 1 from public.task_submissions where task_id=new.id) or exists(select 1 from public.subtask_submissions where task_id=new.id) or exists(select 1 from public.subtask_progress_updates where task_id=new.id) or exists(select 1 from public.work_budget_allocations where task_id=new.id) or exists(select 1 from public.petty_cash_requests where task_id=new.id) then raise exception 'Started, staffed or funded work cannot become proposed responsibility' using errcode='42501';end if;
 end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.phase6_guard_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.projects; t public.tasks; candidate uuid; actor uuid:=auth.uid();
begin if tg_op='UPDATE' and eflow_phase6.project_deletion_detach(to_jsonb(old),to_jsonb(new)) then return new;end if;
 if tg_op='UPDATE' and eflow_r9.internal(coalesce((select linked_project_id from public.tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)),(select project_id from public.personal_tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)))) then return new;end if;
 if tg_op='UPDATE' and (to_jsonb(new)-array['team_member_ids','team_member_names','updated_at'])=(to_jsonb(old)-array['team_member_ids','team_member_names','updated_at']) and eflow_r7.internal(old.id) then return new;end if;
 if tg_op='UPDATE' and pg_trigger_depth()>1 and (to_jsonb(new)-array['subtask_count','subtask_completed_count','last_activity_at','updated_at'])=(to_jsonb(old)-array['subtask_count','subtask_completed_count','last_activity_at','updated_at']) then return new;end if;
 if tg_op in ('DELETE','UPDATE') then t:=old;else t:=new;end if;
 select * into p from public.projects where id=t.linked_project_id;
 if p.id is null or p.source_collaboration_draft_id is not null or not eflow_phase6.shared(p.id) then if tg_op='DELETE' then return old;else return new;end if;end if;
 -- Maintenance via service_role remains available; JWT users cannot bypass it
 -- through definer RPCs because auth.uid() remains their original identity.
 if actor is not null then
  if p.status in ('completed','archived') then raise exception 'Closed project work is read-only' using errcode='42501';end if;
  if tg_op='UPDATE' and (new.linked_project_id is distinct from old.linked_project_id or new.source_collaboration_draft_id is distinct from old.source_collaboration_draft_id) then raise exception 'Project identity is protected' using errcode='42501';end if;
  if tg_op='UPDATE' and new.org_id is distinct from old.org_id then
   if not public.phase2_is_office_head(actor,p.org_id) or old.status<>'pending_assignment' or old.assigned_to is not null or old.recommendation_lead_id is not null or cardinality(coalesce(old.team_member_ids,'{}'::uuid[]))>0 or exists(select 1 from public.subtasks where task_id=old.id and (status<>'todo' or assigned_to is not null or cardinality(coalesce(assigned_to_ids,'{}'::uuid[]))>0)) or new.assigned_to is not null or new.recommendation_lead_id is not null or cardinality(coalesce(new.team_member_ids,'{}'::uuid[]))>0 then raise exception 'Office handover requires unstarted, unassigned work' using errcode='42501';end if;
  elsif tg_op='INSERT' then
   if not eflow_phase6.head(p.id,t.org_id,actor) then raise exception 'Only the responsible Office Head can create work' using errcode='42501';end if;
  elsif not eflow_phase6.work(t.id,actor) and not (tg_op='UPDATE' and public.phase2_is_office_head(actor,p.org_id) and (to_jsonb(new)-array['group_id','workspace_position','updated_at'])=(to_jsonb(old)-array['group_id','workspace_position','updated_at'])) then raise exception 'Your project access is read-only for this Office work' using errcode='42501';end if;
  if tg_op='UPDATE' and (new.assigned_to is distinct from old.assigned_to or new.recommendation_lead_id is distinct from old.recommendation_lead_id or new.team_member_ids is distinct from old.team_member_ids or new.team_id is distinct from old.team_id) and not eflow_phase6.head(p.id,new.org_id,actor) then raise exception 'Only the responsible Office Head can choose its employees' using errcode='42501';end if;
 end if;
 if tg_op<>'DELETE' then
  if not exists(select 1 from public.project_offices where project_id=p.id and office_id=new.org_id and relationship_type in ('lead','collaborating') and invitation_status='joined') then raise exception 'Responsible Office must be a joined collaborator' using errcode='23514';end if;
  foreach candidate in array array_remove(array[new.assigned_to,new.recommendation_lead_id]||coalesce(new.team_member_ids,'{}'::uuid[]),null) loop
   if not exists(select 1 from public.profiles q where q.id=candidate and q.org_id=new.org_id and q.is_active and q.role<>'admin' and (public.phase2_is_office_head(candidate,new.org_id) or new.org_id=p.org_id or exists(select 1 from public.project_office_members m join public.project_offices o on o.id=m.project_office_id where o.project_id=p.id and o.office_id=new.org_id and m.user_id=candidate))) then raise exception 'Select active project members from the responsible Office' using errcode='42501';end if;
  end loop;
  return new;
 end if;return old;
end $function$

CREATE OR REPLACE FUNCTION eflow_phase7.material_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pid uuid;previous uuid;p public.projects; changed boolean:=true;
begin
 if tg_table_name='tasks' then
  if tg_op<>'DELETE' then pid:=new.linked_project_id;end if;
  if tg_op<>'INSERT' then previous:=old.linked_project_id;end if;
  if tg_op='UPDATE' then changed:=row(new.description,new.org_id,new.start_date,new.deadline,new.dependency_ids,new.budget_impact,new.deleted_at,new.linked_project_id,new.acceptance_criteria,new.definition_of_done,new.status='cancelled') is distinct from row(old.description,old.org_id,old.start_date,old.deadline,old.dependency_ids,old.budget_impact,old.deleted_at,old.linked_project_id,old.acceptance_criteria,old.definition_of_done,old.status='cancelled');end if;
 else
  if tg_op<>'DELETE' then pid:=new.project_id;end if;
  if tg_op<>'INSERT' then previous:=old.project_id;end if;
  if tg_op='UPDATE' then changed:=row(new.office_id,new.relationship_type,new.invitation_status) is distinct from row(old.office_id,old.relationship_type,old.invitation_status);end if;
 end if;
 if not changed then return null;end if;
 -- All relevant writes and activation serialize on the project row, preventing
 -- a stale readiness result from racing with an ownership/scope change.
 for p in select * from public.projects where id in (pid,previous) order by id for update loop
  if p.source_collaboration_draft_id is null and p.status='active' then
   update public.projects set status='on_hold',updated_at=now() where id=p.id;
   insert into public.audit_events(actor_id,entity_type,entity_id,action,org_id,after_data) values(auth.uid(),'project',p.id::text,'project.material_change_review',p.org_id,jsonb_build_object('source',tg_table_name,'status','on_hold'));
  end if;
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION eflow_r3.disjoint_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.id::text,1));
 if (tg_table_name='personal_projects' and exists(select 1 from public.projects where id=new.id))
 or (tg_table_name='projects' and exists(select 1 from public.personal_projects where id=new.id))
 or (tg_table_name='personal_tasks' and (exists(select 1 from public.tasks where id=new.id) or exists(select 1 from public.subtasks where id=new.id)))
 or (tg_table_name in ('tasks','subtasks') and exists(select 1 from public.personal_tasks where id=new.id)) then
 raise exception 'Personal and Office identities must be disjoint' using errcode='22023';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_r7.guard_root()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid;v_internal boolean;begin if tg_op='UPDATE' and eflow_r9.internal(coalesce((select linked_project_id from public.tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)),(select project_id from public.personal_tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)))) then return new;end if;
 if tg_table_name='tasks' then
  if new.linked_project_id is null or new.source_collaboration_draft_id is not null then return new;end if;
  if tg_op='INSERT' or new.assigned_to is distinct from old.assigned_to or new.recommendation_lead_id is distinct from old.recommendation_lead_id or new.team_member_ids is distinct from old.team_member_ids then
   if auth.uid() is not null and (tg_op='INSERT' or new.assigned_to is distinct from old.assigned_to or new.recommendation_lead_id is distinct from old.recommendation_lead_id or not eflow_r7.internal(new.id)) and not eflow_phase6.head(new.linked_project_id,new.org_id,auth.uid()) then raise exception 'Only the appointed responsible Head transfers the root lead; contributors use the narrow operation' using errcode='42501';end if;
   foreach uid in array array_remove(array[coalesce(new.assigned_to,new.recommendation_lead_id)]||coalesce(new.team_member_ids,'{}'::uuid[]),null) loop
    if not eflow_r7.member(new.linked_project_id,new.org_id,uid) then raise exception 'Select an active selected project member' using errcode='42501';end if;
   end loop;
  end if;
  if tg_op='UPDATE' and coalesce(new.assigned_to,new.recommendation_lead_id) is distinct from coalesce(old.assigned_to,old.recommendation_lead_id) then
   v_internal:=eflow_r7.internal(new.id);
   insert into eflow_r7.mutations values(txid_current(),auth.uid(),new.id) on conflict do nothing;
   update public.subtasks set lead_id=null where task_id=new.id and lead_id is not null;
   if not v_internal then delete from eflow_r7.mutations where tx=txid_current() and actor=auth.uid() and root_id=new.id;end if;
  end if;
 else
  if tg_op='UPDATE' and new.lead_id is distinct from old.lead_id then
   v_internal:=eflow_r7.internal(new.id);insert into eflow_r7.mutations values(txid_current(),auth.uid(),new.id) on conflict do nothing;
   update public.personal_subtasks set lead_id=null where task_id=new.id;
   if not v_internal then delete from eflow_r7.mutations where tx=txid_current() and actor=auth.uid() and root_id=new.id;end if;
  end if;
  if new.status in ('submitted','done') and exists(select 1 from public.personal_subtasks where task_id=new.id and status<>'completed') then raise exception 'Complete and review every descendant before completing the root';end if;
 end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_task_financial_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'completed' and old.status is distinct from 'completed' and exists (
    select 1 from public.petty_cash_requests request where request.task_id = new.id
      and request.status not in ('settled', 'rejected', 'cancelled')
  ) then raise exception 'Settle all task and subtask cash before approving this task' using errcode = '22023'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_task_dependency_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare required_count integer; completed_count integer;
begin
  if new.status::text not in ('for_review','completed') or cardinality(coalesce(new.dependency_ids,'{}'::uuid[]))=0 then return new; end if;
  required_count := cardinality(new.dependency_ids);
  perform 1 from public.tasks t where t.id=any(new.dependency_ids) order by t.id for share;
  select count(*) into completed_count from public.tasks t
    where t.id=any(new.dependency_ids) and t.linked_project_id is not distinct from new.linked_project_id and t.status::text='completed';
  if completed_count<>required_count then
    raise exception 'Wait for prerequisite task approval before final submission.' using errcode='22023';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.guard_active_subtask_team_member_removal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  removed_ids uuid[];
  blocked_member_name text;
  blocked_subtask_title text;
begin
  if new.team_member_ids is not distinct from old.team_member_ids then
    return new;
  end if;

  select coalesce(array_agg(member_id), '{}'::uuid[])
  into removed_ids
  from unnest(coalesce(old.team_member_ids, '{}'::uuid[])) member_id
  where not (member_id = any(coalesce(new.team_member_ids, '{}'::uuid[])));

  if cardinality(removed_ids) = 0 then
    return new;
  end if;

  select coalesce(profile.full_name, 'A task member'), subtask.title
  into blocked_member_name, blocked_subtask_title
  from public.subtasks subtask
  cross join lateral unnest(coalesce(subtask.assigned_to_ids, '{}'::uuid[])) assignee_id
  left join public.profiles profile on profile.id = assignee_id
  where subtask.task_id = old.id
    and coalesce(subtask.status, 'todo') <> 'completed'
    and not coalesce(subtask.is_completed, false)
    and assignee_id = any(removed_ids)
  order by subtask.position, subtask.created_at
  limit 1;

  if blocked_subtask_title is not null then
    raise exception '% cannot be removed while assigned to unfinished subtask "%"',
      blocked_member_name,
      blocked_subtask_title
      using errcode = '22023';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_collaboration_task_staffing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  candidate uuid;
  candidate_org uuid;
  caller uuid := auth.uid();
  caller_org uuid;
  changed_candidate uuid;
begin
  if new.source_collaboration_draft_id is null then return new; end if;
  if new.assigned_to is null then raise exception 'Collaboration tasks require a Task Leader' using errcode = '22023'; end if;
  if not (coalesce(new.team_member_ids, '{}'::uuid[]) @> array[new.assigned_to]) then
    raise exception 'Task Leader must belong to the selected team' using errcode = '22023';
  end if;
  foreach candidate in array coalesce(new.team_member_ids, '{}'::uuid[]) loop
    select org_id into candidate_org from public.profiles where id = candidate and is_active;
    if candidate_org is null or not exists (
      select 1 from public.proposal_collaboration_orgs eligible
      where eligible.draft_id = new.source_collaboration_draft_id
        and eligible.org_id = candidate_org and eligible.staffing_enabled
    ) then
      raise exception 'Every collaboration team member must be active and belong to a staffing-enabled participating organization'
      using errcode = '22023';
    end if;
  end loop;
  if tg_op = 'UPDATE' and (
    new.assigned_to is distinct from old.assigned_to
    or coalesce(new.team_member_ids, '{}'::uuid[]) is distinct from coalesce(old.team_member_ids, '{}'::uuid[])
  ) then
    select org_id into caller_org from public.profiles where id = caller and is_active;
    if new.assigned_to is distinct from old.assigned_to
       and not exists (select 1 from public.profiles where id = new.assigned_to and org_id = caller_org and is_active) then
      raise exception 'Changing a cross-organization Task Leader requires approval from that employee''s organization'
        using errcode = '42501';
    end if;
    foreach changed_candidate in array (
      select coalesce(array_agg(member_id), '{}'::uuid[])
      from (
        (select unnest(coalesce(new.team_member_ids, '{}'::uuid[])) member_id
         except select unnest(coalesce(old.team_member_ids, '{}'::uuid[])))
        union
        (select unnest(coalesce(old.team_member_ids, '{}'::uuid[])) member_id
         except select unnest(coalesce(new.team_member_ids, '{}'::uuid[])))
      ) changes
    ) loop
      if not exists (select 1 from public.profiles where id = changed_candidate and org_id = caller_org) then
        raise exception 'Cross-organization staffing changes require approval from the employee''s organization'
          using errcode = '42501';
      end if;
    end loop;
  end if;
  if new.review_route_mode = 'governance' then
    if new.reviewer_id is null then raise exception 'Governed tasks require an active Board reviewer' using errcode = '22023'; end if;
    if new.reviewer_id = new.assigned_to or new.backup_reviewer_id = new.assigned_to then
      raise exception 'Task Leader cannot review their own Task' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_task_project_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.milestone_id is null then return new; end if;
  if new.linked_project_id is null then
    raise exception 'A milestone link requires a canonical project link'
      using errcode = '23514';
  end if;
  if not exists (
    select 1
    from public.milestones
    where id = new.milestone_id
      and project_id = new.linked_project_id
  ) then
    raise exception 'Milestone does not belong to the linked project'
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_task_submission_readiness()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  unresolved_count int;
begin
  if new.status = 'for_review' and old.status is distinct from 'for_review' then
    select count(*) into unresolved_count
    from unnest(new.dependency_ids) dependency_id
    left join public.tasks dependency on dependency.id = dependency_id
    where dependency.id is null
       or dependency.deleted_at is not null
       or dependency.status <> 'completed';

    if unresolved_count > 0 then
      raise exception 'Complete all task dependencies before submitting for review'
        using errcode = '22023';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.route_organization_leadership_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare office_head uuid;
begin /* NW5.1 preserve historical reviewers */ if tg_op='UPDATE' then if pg_catalog.has_function_privilege(current_user,'eflow_r9.staffing_removal_allowed(text,jsonb,jsonb)','EXECUTE') then if eflow_r9.staffing_removal_allowed(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new;end if;end if;end if;
  if coalesce(new.review_route_mode,'organization_default') <> 'organization_default' then return new; end if;
  if new.assigned_to is null then return new; end if;
  select o.head_user_id into office_head from public.organizations o
    where o.id=new.org_id and public.is_office_output_reviewer(o.id,o.head_user_id);
  new.reviewer_id := office_head;
  new.backup_reviewer_id := null;
  if new.status='for_review' and office_head is null then
    raise exception 'Assign an active Head for the responsible office before submitting' using errcode='22023';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_task_chat_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_channel_id uuid;
  v_member_ids uuid[];
begin /* NW5.1 current chat access only */ if tg_op='UPDATE' and eflow_r9.staffing_removal_allowed(tg_table_name,to_jsonb(old),to_jsonb(new)) then delete from public.chat_channel_members c using public.chat_channels h,eflow_r9.staffing_removals m where c.channel_id=h.id and h.task_id=new.id and m.tx=pg_catalog.pg_current_xact_id() and m.relation_name=tg_table_name and m.row_id=new.id and c.user_id=m.removed_user;return new;end if;
  v_member_ids := array(
    select distinct member_id
    from unnest(
      array[new.assigned_to::uuid]
      || coalesce(new.team_member_ids::uuid[], '{}'::uuid[])
    ) as member_id
    where member_id is not null
  );

  if coalesce(cardinality(v_member_ids), 0) = 0 then
    return new;
  end if;

  select id into v_channel_id
  from public.chat_channels
  where task_id = new.id;

  if v_channel_id is null then
    insert into public.chat_channels (channel_type, task_id, name)
    values ('task', new.id, new.title)
    returning id into v_channel_id;
  else
    update public.chat_channels
    set name = new.title
    where id = v_channel_id;
  end if;

  delete from public.chat_channel_members as channel_member
  where channel_member.channel_id = v_channel_id
    and channel_member.user_id <> all(v_member_ids);

  insert into public.chat_channel_members (channel_id, user_id)
  select v_channel_id, member_id
  from unnest(v_member_ids) as member_id
  on conflict (channel_id, user_id) do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_task_reviewers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  reviewer_active boolean;
begin /* NW5.1 preserve historical reviewers */ if tg_op='UPDATE' then if pg_catalog.has_function_privilege(current_user,'eflow_r9.staffing_removal_allowed(text,jsonb,jsonb)','EXECUTE') then if eflow_r9.staffing_removal_allowed(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new;end if;end if;end if;
  if new.reviewer_id is not null then
    if new.reviewer_id = new.assigned_to and not (new.review_route_mode='organization_default' and public.is_office_output_reviewer(new.org_id,new.reviewer_id)) then
      raise exception 'The assignee cannot review their own task'
        using errcode = '22023';
    end if;
    select is_active and role <> 'admin' into reviewer_active
    from public.profiles where id = new.reviewer_id;
    if not coalesce(reviewer_active, false) then
      raise exception 'Primary reviewer must be an active profile'
        using errcode = '22023';
    end if;
  end if;

  if new.backup_reviewer_id is not null then
    if new.backup_reviewer_id = new.assigned_to
       or new.backup_reviewer_id = new.reviewer_id then
      raise exception 'Backup reviewer must differ from assignee and primary reviewer'
        using errcode = '22023';
    end if;
    select is_active and role <> 'admin' into reviewer_active
    from public.profiles where id = new.backup_reviewer_id;
    if not coalesce(reviewer_active, false) then
      raise exception 'Backup reviewer must be an active profile'
        using errcode = '22023';
    end if;
  end if;

  return new;
end;
$function$

